function audioRoom(){
document.activeElement?.blur?.();
app.innerHTML='<div class=navline><button id=audioBack>رجع للتدريب</button><span class=cap>تسجيلات الكتاب الأصلية</span></div><section class=card><h2>مختبر السمع</h2><p>اختار CD ورقم المسار اللي مكتوب حدّ التمرين فالكتاب. التسجيلات والصفحات الأصلية ديال الكتاب. اختار المسار ورقم الصفحة حسب رمز الصوت فالكتاب.</p><div class=fields><label>القرص<select id=disc><option value=1>CD 1</option><option value=2>CD 2</option></select></label><label>المسار<select id=track></select></label></div><p id=audioLabel></p><audio id=bookPlayer controls preload=none style="width:100%"></audio><div class=grid><button id=repeatPart>رجع 5 ثواني</button><button id=repeatToggle aria-pressed=false>تكرار المسار: لا</button></div><label>سرعة القراءة<select id=rate><option value=.75>0.75×</option><option value=1 selected>1× الأصلية</option><option value=1.25>1.25×</option></select></label><p id=audioStatus role=status></p></section><section class=card><h2>سمع • ردّد • كتب</h2><p>1. سمع مرة بلا كتابة. 2. عاود وردّد جملة بجملة. 3. كتب شنو فهمتي وقارن بالنص فالكتاب. هاد المسودة بلا تصحيح آلي.</p><textarea id=listeningDraft dir=ltr aria-label="مسودة السمع" placeholder="Was hast du gehört?"></textarea><p id=draftStatus></p></section>';
const reader=document.createElement('section');reader.className='card';$('#bookPlayer').closest('section').after(reader);reader.innerHTML='<button id=openWrittenReader class=reader-entry>📖 قرا النص مكتوب وجاوب<small>القسم الجديد مرتب حسب الفصول</small></button><h2>النص والتمرين من الكتاب</h2><p id=pageMatch></p><label>الفصل<select id=bookChapter></select></label><label>رقم الصفحة المطبوعة<input id=bookPage type=number inputmode=numeric min=9 max=254 value=9></label><button id=showPage>شوف الصفحة • النص والأسئلة</button><button id=rememberPage>ربط هاد الصفحة بالمسار المختار عندي</button><details id=pageReveal><summary>إظهار أو إخفاء الصفحة</summary><p class=tip>جرّب تجاوب قبل ما تكشف النص. فبعض التمارين كاينين غير الأسئلة؛ ماشي كل صفحة فيها تفريغ التسجيل.</p><a id=fullPage target=_blank rel=noopener>فتح الصفحة بحجم كبير</a><img id=pageImage loading=lazy alt="صفحة الكتاب الأصلية: النص والأسئلة" style="display:block;width:100%;height:auto;margin-top:12px;background:white;border-radius:8px"></details><label>أجوبتي على تمرين الكتاب<textarea id=exerciseAnswer dir=ltr placeholder="1. … 2. …"></textarea></label><p>الأجوبة كتتحفظ تلقائياً فهاد الجهاز لكل مسار وصفحة. ما كاينش تصحيح آلي للتمرين الأصلي.</p>';
const starts=[9,27,49,71,93,113,133,153,173,193,213,235];$('#bookChapter').innerHTML=starts.map((n,i)=>'<option value='+n+'>Kapitel '+(i+1)+'</option>').join('');
let readerKey='';const knownPages=AUDIO_PAGE_MAP;let localPages={},answers={};try{localPages=JSON.parse(localStorage.wrAudioPages||'{}');answers=JSON.parse(localStorage.wrBookAnswers||'{}')}catch{}
function displayPage(open=false){let n=+$('#bookPage').value;if(!Number.isInteger(n)||n<9||n>254){$('#pageMatch').textContent='اختار صفحة بين 9 و254.';return}$('#pageImage').src='book-pages/'+n+'.jpg';$('#fullPage').href='book-pages/'+n+'.jpg';$('#pageReveal').open=open;readerKey=$('#disc').value+'-'+$('#track').value+'-'+n;$('#exerciseAnswer').value=answers[readerKey]||'';$('#bookChapter').value=starts.filter(v=>v<=n).pop()}
$('#showPage').onclick=()=>displayPage(true);$('#bookChapter').onchange=e=>{$('#bookPage').value=e.target.value;displayPage(true)};$('#exerciseAnswer').oninput=e=>{answers[readerKey]=e.target.value;try{localStorage.wrBookAnswers=JSON.stringify(answers)}catch{}};
$('#rememberPage').onclick=()=>{let n=+$('#bookPage').value;if(n<9||n>254||!Number.isInteger(n))return;localPages[$('#disc').value+'-'+$('#track').value]=n;try{localStorage.wrAudioPages=JSON.stringify(localPages)}catch{}$('#pageMatch').textContent='حفظت اختيار الصفحة ديالك لهاد المسار.'};
$('#openWrittenReader').onclick=()=>{const pg=AUDIO_PAGE_MAP[$('#disc').value+'-'+$('#track').value];if(pg){const r=READER_PAGES.find(x=>x.page===pg);$('#bookPlayer').pause();readingRoom(r.ch,pg)}else{$('#bookPlayer').pause();readingRoom()}};
const player=$('#bookPlayer'),disc=$('#disc'),track=$('#track'),draft=$('#listeningDraft');let active;st.lab.audio??={};st.lab.audioDrafts??={};
function saveDraft(){if(active){st.lab.audioDrafts[active.disc+'-'+active.n]=draft.value;save()}}
function select(){saveDraft();active=BOOK_AUDIO.find(t=>t.disc===+disc.value&&t.n===+track.value);let k=active.disc+'-'+active.n,mapped=localPages[k]||knownPages[k];$('#bookPage').value=mapped||$('#bookPage').value;$('#pageMatch').textContent=localPages[k]?'الصفحة المختارة من طرفك.':knownPages[k]?'مطابقة متحققة من رمز الصوت فالصفحة.':'اختار الصفحة حسب رمز CD والمسار فالكتاب. هاد المسار مازال ما تربطش تلقائياً.';displayPage(false);player.pause();player.src=active.src;player.load();player.playbackRate=+$('#rate').value;draft.value=st.lab.audioDrafts[active.disc+'-'+active.n]||'';$('#audioLabel').textContent='CD '+active.disc+' · Track '+active.n+' · '+Math.floor(active.duration/60)+':'+String(active.duration%60).padStart(2,'0');st.lab.audio={disc:active.disc,n:active.n};save();$('#audioStatus').textContent='ضغط على التشغيل. غير المسار المختار هو اللي كيتحمّل.'}
function fill(n){track.innerHTML=BOOK_AUDIO.filter(t=>t.disc===+disc.value).map(t=>'<option value='+t.n+'>'+t.n+'</option>').join('');if(n&&BOOK_AUDIO.some(t=>t.disc===+disc.value&&t.n===n))track.value=n;select()}
disc.value=st.lab.audio.disc||1;disc.onchange=()=>fill();track.onchange=select;$('#rate').onchange=()=>player.playbackRate=+$('#rate').value;$('#repeatPart').onclick=()=>player.currentTime=Math.max(0,player.currentTime-5);$('#repeatToggle').onclick=e=>{player.loop=!player.loop;e.target.textContent='تكرار المسار: '+(player.loop?'نعم':'لا');e.target.setAttribute('aria-pressed',player.loop)};
player.onerror=()=>$('#audioStatus').textContent='تعذّر تحميل التسجيل. تأكد من الإنترنت وعاود اختار المسار.';draft.oninput=()=>{saveDraft();$('#draftStatus').textContent='المسودة تحفظات فهاد الجهاز. الحفظ فالحساب من الإعدادات.'};$('#audioBack').onclick=()=>{saveDraft();player.pause();player.removeAttribute('src');home()};fill(st.lab.audio.n)
}
